function distanceToSegment(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,l=dx*dx+dy*dy,t=l?clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/l,0,1):0;return Math.hypot(p.x-(a.x+t*dx),p.y-(a.y+t*dy))}
function eraseAt(p){for(let i=routes.length-1;i>=0;i--){const pts=routes[i].points;if(pts.some((v,j)=>j>0&&distanceToSegment(p,pts[j-1],v)<.035)){routes.splice(i,1);state.notice='ROUTE ERASED';state.noticeTime=1.5;return true}}return false}
function nearestFire(){let best=null,bd=Infinity;fires.forEach(f=>{if(f.size<=0)return;const d=Math.hypot(player.x-f.x,player.y-f.y);if(d<bd){bd=d;best=f}});return{fire:best,d:bd}}
function spray(){const {fire,d}=nearestFire();if(!fire||d>.22)return;const ang=Math.atan2(fire.y-player.y,fire.x-player.x);let diff=Math.atan2(Math.sin(ang-player.angle),Math.cos(ang-player.angle));if(Math.abs(diff)>.65)return;
  const compatible=(fire.type==='A'&&state.selected==='water'||fire.type==='C'&&state.selected==='co2'||fire.type==='B'&&state.selected==='dry'||fire.type==='K'&&state.selected==='wet');
  if(!compatible){if(state.selected==='water'&&(fire.type==='C'||fire.type==='K')){fire.size=Math.min(1,fire.size+.05);state.score=Math.max(0,state.score-1.6);if(Math.random()<.025){state.notice=fire.type==='C'?'⚠ WATER ON ELECTRICAL — ARC FLASH!':'⚠ WATER ON GREASE — FIRE SPREAD!';state.noticeTime=1.4}}else if(Math.random()<.025){state.notice=`WRONG AGENT · USE ${fire.type==='A'?'WATER':fire.type==='C'?'CO₂':fire.type==='K'?'WET CHEM':'DRY CHEM'}`;state.noticeTime=1.2}return}
  fire.size=Math.max(0,fire.size-.0038);if(Math.random()<.38){let p=world(player.x,player.y);particles.push({x:p.x,y:p.y,r:(2+Math.random()*3)*ui,color:state.selected==='co2'?'#d8f6ff':state.selected==='water'?'#b9e8ff':'#f2e8c6',vx:Math.cos(player.angle)+(Math.random()-.5)*.4,vy:Math.sin(player.angle)+(Math.random()-.5)*.4,life:1})}
  if(fire.size===0&&!fire.done){fire.done=true;state.extinguished++;state.points+=250;state.notice=`${fire.label} EXTINGUISHED · WELL DONE`;state.noticeTime=3;if(state.extinguished===3){state.complete=true;state.score=Math.max(0,Math.round(state.score-(3-civilians.filter(c=>c.done).length)*3));}}
}
function beginDrill(){if(state.phase!=='PREP')return;state.phase='LIVE';state.seconds=90;state.score=100;let safeRoutes=routes.filter(r=>checkPathSafety(r.points,hazards));if(!safeRoutes.length){state.score-=20;state.notice='NO SAFE ROUTES · EVACUATION SCORE AT RISK'}else state.notice='DRILL LIVE · EXTINGUISH ALL FIRES';if(sockets.filter(s=>s.type).length<2)state.score-=10;state.noticeTime=4;fires.forEach(f=>{f.size=.72;f.done=false});civilians.forEach((c,i)=>{c.x=.46+i*.035;c.y=.48+i*.025;c.done=false;c.route=0;c.progress=0})}
function selectWheelAt(x,y){const isExt=state.wheel==='ext',anchor=screenButton(isExt?'ext':'plan'),list=isExt?tools:planning;let angle=Math.atan2(y-anchor.y,x-anchor.x);if(angle< -Math.PI/2)angle+=Math.PI*2;let index=Math.round((angle+Math.PI/2)/(Math.PI*2/list.length))%list.length;const item=list[index];if(isExt){state.selected=item.id;state.notice=`${item.name} EXTINGUISHER READY`;state.noticeTime=1.5}else{state.tool=item.id;state.notice=item.id==='route'?'ROUTE PAINTER READY · DRAG A SAFE LINE':item.id==='install'?'INSTALLER READY · TAP A WALL SOCKET':'DANGER MARKER · TAP A BLAST ZONE';state.noticeTime=2}state.wheel=null}
function hitCircle(x,y,b){return Math.hypot(x-b.x,y-b.y)<b.r+5*ui}
function pointerDown(e){e.preventDefault();const x=e.offsetX,y=e.offsetY,id=e.pointerId;canvas.setPointerCapture(id);pointerMap.set(id,{x,y,startX:x,startY:y});
  if(state.complete){if(y>H*.55){state.complete=false;state.phase='PREP';state.seconds=120;state.extinguished=0;state.rescued=0;state.score=100;routes=[];sockets.forEach(s=>s.type=null);fires.forEach(f=>{f.size=0;f.done=false});state.notice='PLAN YOUR SAFE EVACUATION ROUTES';state.noticeTime=3}return}
  if(state.wheel){selectWheelAt(x,y);return}
  if(hitCircle(x,y,{x:W-65*ui,y:31*ui,r:57*ui})){beginDrill();return}
  const m=screenButton('move'),f=screenButton('fire'),ext=screenButton('ext'),plan=screenButton('plan');
  if(hitCircle(x,y,m)){movePointer=id;updateMove(x,y);return}
  if(hitCircle(x,y,f)){sprayPointer=id;spray();return}
  if(hitCircle(x,y,ext)){state.wheel='ext';return}
  if(hitCircle(x,y,plan)){state.wheel='plan';return}
  if(y>=map.y&&y<=map.y+map.h&&x>=map.x&&x<=map.x+map.w){const p=norm(x,y);
    if(state.phase==='PREP'&&state.tool==='route'){if(!eraseAt(p)){activeRoute={points:[p]};pointerMap.get(id).route=true}}
    else if(state.phase==='PREP'&&state.tool==='install'){let s=sockets.find(q=>Math.hypot(q.x-p.x,q.y-p.y)<.06);if(s){s.type=state.selected;state.notice=`${toolById(s.type).name} MOUNTED`;state.noticeTime=2}else{state.notice='TAP A WALL SOCKET TO INSTALL';state.noticeTime=1.5}}
    else if(state.phase==='PREP'&&state.tool==='danger'){let z=hazards.find(q=>Math.hypot(q.x-p.x,q.y-p.y)<.16);if(z){z.mitigated=!z.mitigated;state.notice=z.mitigated?'BLAST ZONE MITIGATED':'BLAST ZONE ACTIVE';state.noticeTime=2}else{state.notice='TAP A RED BLAST ZONE TO MITIGATE';state.noticeTime=1.5}}
    else if(state.phase==='LIVE'){const dx=p.x-player.x,dy=p.y-player.y;player.angle=Math.atan2(dy,dx)}return
  }
  // Right-side aiming drag (separate pointer allows simultaneous movement)
  if(x>W*.52&&y>H-190*ui){aimPointer=id;updateAim(x,y);return}
}
function pointerMove(e){e.preventDefault();const x=e.offsetX,y=e.offsetY,id=e.pointerId,p=pointerMap.get(id);if(!p)return;p.x=x;p.y=y;
  if(id===movePointer){updateMove(x,y);return}if(id===aimPointer){updateAim(x,y);return}if(id===sprayPointer){spray();return}
  if(p.route&&activeRoute){let q=norm(x,y);if(q.x>=0&&q.x<=1&&q.y>=0&&q.y<=1){const tail=activeRoute.points[activeRoute.points.length-1];if(Math.hypot(q.x-tail.x,q.y-tail.y)>.012)activeRoute.points.push(q)}return}
  if(state.phase==='PREP'&&state.tool==='route'&&p.startX>map.x&&p.startX<map.x+map.w&&Math.hypot(x-p.startX,y-p.startY)>10){let q=norm(x,y);if(q.x>=0&&q.x<=1&&q.y>=0&&q.y<=1){if(!activeRoute){eraseAt(norm(p.startX,p.startY));activeRoute={points:[norm(p.startX,p.startY)]};p.route=true}else if(Math.hypot(q.x-activeRoute.points.at(-1).x,q.y-activeRoute.points.at(-1).y)>.012)activeRoute.points.push(q)}}
}
function pointerUp(e){e.preventDefault();let id=e.pointerId,p=pointerMap.get(id);if(p&&p.route&&activeRoute){if(activeRoute.points.length>1){routes.push(activeRoute);if(isUnsafe(activeRoute.points)){state.notice='UNSAFE ROUTE: EVACUEES AT EXPLOSION RISK';state.noticeTime=3}else{state.notice='SAFE ROUTE PAINTED';state.noticeTime=1.7}}activeRoute=null}
  if(id===movePointer){movePointer=null;moveVec={x:0,y:0}}if(id===aimPointer){aimPointer=null;aimVec={x:0,y:0}}if(id===sprayPointer)sprayPointer=null;pointerMap.delete(id)}
function updateMove(x,y){const m=screenButton('move'),dx=x-m.x,dy=y-m.y,d=Math.hypot(dx,dy),max=39*ui,k=d>max?max/d:1;moveVec={x:dx*k/max,y:dy*k/max}}
function updateAim(x,y){const cx=W-176*ui,cy=H-72*ui,dx=x-cx,dy=y-cy,d=Math.hypot(dx,dy)||1;aimVec={x:clamp(dx/d,-1,1),y:clamp(dy/d,-1,1)};player.angle=Math.atan2(dy,dx)}
canvas.addEventListener('pointerdown',pointerDown);canvas.addEventListener('pointermove',pointerMove);canvas.addEventListener('pointerup',pointerUp);canvas.addEventListener('pointercancel',pointerUp);canvas.addEventListener('contextmenu',e=>e.preventDefault());
function update(dt){if(state.noticeTime>0)state.noticeTime-=dt;if(state.phase==='PREP'){state.seconds=Math.max(0,state.seconds-dt)}else if(state.phase==='LIVE'&&!state.complete){state.seconds-=dt;if(state.seconds<=0){state.seconds=0;state.complete=true;state.score=Math.max(0,Math.round(state.score-18));state.notice='TIME EXPIRED';state.noticeTime=3}}
  const speed=.27*dt;player.x=clamp(player.x+moveVec.x*speed,.03,.97);player.y=clamp(player.y+moveVec.y*speed,.06,.94);
  if(aimPointer!==null&&Math.hypot(aimVec.x,aimVec.y)>.1)player.angle=Math.atan2(aimVec.y,aimVec.x);
  if(sprayPointer!==null)spray();
  // Explosion danger zones can be mitigated with the danger marker.
  hazards.forEach(z=>{if(z.mitigated)z.safe=true});
  particles=particles.filter(p=>p.life>0);particles.forEach(p=>{p.x+=p.vx*2;p.y+=p.vy*2;p.life-=dt*1.1;p.r*=.994});
  // NPCs only follow complete, safe routes that terminate at an exit.
  if(state.phase==='LIVE'){civilians.forEach(c=>{if(c.done)return;let route=routes.find(r=>checkPathSafety(r.points,hazards)&&r.points.length>2);if(!route)return;let pts=route.points,ends=pts.map((v,i)=>({v,i,ed:Math.min(...exits.map(e=>Math.hypot(e.x-v.x,e.y-v.y)))}));let end=ends[0].ed<ends.at(-1).ed?0:pts.length-1;let sequence=end===0?[...pts].reverse():pts;let target=sequence[Math.min(Math.floor(c.progress),sequence.length-1)];let dx=target.x-c.x,dy=target.y-c.y,d=Math.hypot(dx,dy);if(d<.018){if(c.progress>=sequence.length-1){c.done=true;state.rescued++;state.points+=100;if(state.rescued===3&&state.extinguished===3){state.complete=true;state.notice='ALL PERSONNEL SAFE · DRILL PASSED';state.noticeTime=5}}else c.progress+=1}else{c.x+=dx/d*dt*.09;c.y+=dy/d*dt*.09}})}
}
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;update(dt);render();requestAnimationFrame(frame)}requestAnimationFrame(frame);
})();
</script></body></html>

